// Me defines model for Me.
type Me struct {
	// ActiveAcademicYear Omitted when the tenant has no active academic year.
	ActiveAcademicYear *struct {
		Id    openapi_types.UUID `json:"id"`
		Label string             `json:"label"`
	} `json:"active_academic_year,omitempty"`
	AvatarUrl *string `json:"avatar_url,omitempty"`

	// CurrentClass The student's class from their active enrollment in the active academic year. Only set for
	// students; omitted for every other profile kind, for students with no active enrollment, and when
	// the tenant has no active academic year. Parents read each child's class from GET /v1/me/children.
	CurrentClass *struct {
		Id   openapi_types.UUID `json:"id"`
		Name string             `json:"name"`
	} `json:"current_class,omitempty"`

	// Detail Omitted when the account has no profile_kind (e.g. a role with no student/teacher/staff record).
	Detail *UserProfileFields `json:"detail,omitempty"`
	Duties *[]struct {
		ScopeId    *openapi_types.UUID `json:"scope_id,omitempty"`
		ScopeKind  MeDutiesScopeKind   `json:"scope_kind"`
		ScopeLabel *string             `json:"scope_label,omitempty"`
		Slug       string              `json:"slug"`
	} `json:"duties,omitempty"`
	Email *string            `json:"email,omitempty"`
	Id    openapi_types.UUID `json:"id"`

	// ImpersonatedBy Present only during an impersonation session.
	ImpersonatedBy *struct {
		Name   *string             `json:"name,omitempty"`
		UserId *openapi_types.UUID `json:"user_id,omitempty"`
	} `json:"impersonated_by,omitempty"`
	MustChangePassword bool   `json:"must_change_password"`
	Name               string `json:"name"`

	// Permissions Effective permission codes (role plus active duty permissions).
	Permissions []string       `json:"permissions"`
	ProfileKind *MeProfileKind `json:"profile_kind,omitempty"`
	Roles       []Role         `json:"roles"`
	Tenant      TenantBranding `json:"tenant"`
	Username    string         `json:"username"`
}

